import re
from datetime import date

MONTH_NUMBERS = {}
for _index, _name in enumerate(
    ["january", "february", "march", "april", "may", "june", "july", "august",
     "september", "october", "november", "december"],
    1,
):
    MONTH_NUMBERS[_name] = _index
    MONTH_NUMBERS[_name[:3]] = _index


def to_iso_date(text):
    s = text.strip(" ")
    m = re.fullmatch(r"([A-Za-z]+) (\d{1,2}), (\d{4})", s)
    if m:
        month = MONTH_NUMBERS.get(m.group(1).lower())
        if month is None:
            raise ValueError("unknown month: %r" % m.group(1))
        y, mo, d = int(m.group(3)), month, int(m.group(2))
    else:
        m = re.fullmatch(r"(\d{2})/(\d{2})/(\d{4})", s)
        if m:
            d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        else:
            m = re.fullmatch(r"(\d{4})\.(\d{2})\.(\d{2})", s)
            if not m:
                raise ValueError("unrecognized date: %r" % text)
            y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
    return date(y, mo, d).isoformat()

import re
from datetime import date, datetime

_NAMES = ("jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec")
_FULL = ("january", "february", "march", "april", "may", "june", "july", "august",
         "september", "october", "november", "december")


def to_iso_date(text):
    s = text.strip(" ")
    named = re.fullmatch(r"([A-Za-z]+) (\d{1,2}), (\d{4})", s)
    if named:
        word = named.group(1).lower()
        if word in _FULL:
            month = _FULL.index(word) + 1
        elif word in _NAMES:
            month = _NAMES.index(word) + 1
        else:
            raise ValueError("unknown month %r" % word)
        return date(int(named.group(3)), month, int(named.group(2))).isoformat()
    if re.fullmatch(r"\d{2}/\d{2}/\d{4}", s):
        return datetime.strptime(s, "%d/%m/%Y").date().isoformat()
    if re.fullmatch(r"\d{4}\.\d{2}\.\d{2}", s):
        return datetime.strptime(s, "%Y.%m.%d").date().isoformat()
    raise ValueError("unrecognized date: %r" % text)
